from AlgorithmImports import *
from datetime import timedelta


class SpyBullishCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-500, 500)
                .Expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.consolidator)

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.pending_entry_signal = False
        self.expiration_processing_date = None

        self.profit_target_percent = float(
            self.GetParameter("ProfitTargetPercent") or 50
        )

    def OnFiveMinuteBar(self, sender, bar):
        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if (
            previous_fast is not None
            and previous_slow is not None
            and self.fast.IsReady
            and self.slow.IsReady
            and previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        ):
            end_time = bar.EndTime.astimezone(self.TimeZone)
            if (
                end_time.hour > 9
                or (end_time.hour == 9 and end_time.minute >= 45)
            ) and (
                end_time.hour < 14
                or (end_time.hour == 14 and end_time.minute <= 30)
            ):
                self.pending_entry_signal = True

    def OnData(self, slice):
        current_date = self.Time.date()

        if self.expiration_processing_date != current_date:
            self.expiration_processing_date = None

        if self.held_option is not None:
            expiration_date = self.held_option.ID.Date.date()

            if current_date >= expiration_date:
                self.expiration_processing_date = current_date
                self.LiquidateHeldOption("expiration processing")
            elif self.IsTradingDayImmediatelyBefore(current_date, expiration_date):
                if self.Time.hour > 15 or (
                    self.Time.hour == 15 and self.Time.minute >= 45
                ):
                    self.LiquidateHeldOption("expiration time stop")
            else:
                self.EvaluateProfitTarget(slice)

        if self.Portfolio[self.spy].Invested and self.held_option is None:
            self.Debug(
                f"{self.Time}: unexpected SPY exercise or assignment; "
                "liquidating equity position"
            )
            self.MarketOrder(self.spy, -self.Portfolio[self.spy].Quantity)

        if (
            self.pending_entry_signal
            and self.expiration_processing_date != current_date
            and self.held_option is None
            and not self.HasOpenEntryOrder()
        ):
            self.pending_entry_signal = False
            self.TryEnter(slice)

    def TryEnter(self, slice):
        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug(f"{self.Time}: skipped entry; no option chain")
            return

        current_date = self.Time.date()
        minimum_expiration = current_date + timedelta(days=7)

        contracts = []
        for chain in chains:
            for contract in chain:
                if contract.Right != OptionRight.Call:
                    continue
                if contract.Expiry.date() < minimum_expiration:
                    continue
                contracts.append(contract)

        if not contracts:
            self.Debug(
                f"{self.Time}: skipped entry; no qualifying expiration"
            )
            return

        selected_expiration = min(
            contract.Expiry.date() for contract in contracts
        )

        price = self.Securities[self.spy].Price
        if price <= 0:
            self.Debug(f"{self.Time}: skipped entry; invalid SPY price")
            return

        eligible = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiration
            and contract.Strike >= 1.01 * price
        ]

        if not eligible:
            self.Debug(
                f"{self.Time}: skipped entry; no qualifying call strike"
            )
            return

        selected = min(
            eligible,
            key=lambda contract: (
                contract.Strike,
                str(contract.Symbol)
            )
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(f"{self.Time}: submitted call entry for {selected.Symbol}")

    def EvaluateProfitTarget(self, slice):
        if self.held_option is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            return

        contract = slice.OptionChains.GetValue(self.held_option)
        bid = None
        ask = None

        if contract is not None:
            bid = contract.BidPrice
            ask = contract.AskPrice

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2
        target = self.entry_price * (
            1 + self.profit_target_percent / 100
        )

        if midpoint >= target:
            self.LiquidateHeldOption("profit target")

    def LiquidateHeldOption(self, reason):
        if self.held_option is None:
            return

        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            return

        for ticket in self.Transactions.GetOpenOrderTickets(self.held_option):
            ticket.Cancel("replaced by liquidation")

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity != 0:
            self.exit_ticket = self.MarketOrder(
                self.held_option,
                -quantity
            )
            self.Debug(
                f"{self.Time}: submitted option exit ({reason})"
            )

    def HasOpenEntryOrder(self):
        return (
            self.entry_ticket is not None
            and not self.entry_ticket.Status.IsClosed()
        )

    def IsTradingDayImmediatelyBefore(self, current_date, expiration_date):
        candidate = current_date + timedelta(days=1)
        while candidate < expiration_date:
            if self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate):
                return True
            candidate += timedelta(days=1)
        return False

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_option = self.entry_ticket.Symbol
                    self.entry_price = order_event.FillPrice
                    self.Debug(
                        f"{self.Time}: call entry filled at "
                        f"{self.entry_price}"
                    )
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.None_
                ):
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        f"{self.Time}: option exit filled at "
                        f"{order_event.FillPrice}"
                    )
                    self.held_option = None
                    self.entry_price = None
                    self.exit_ticket = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.exit_ticket = None

        if (
            order_event.Symbol == self.spy
            and order_event.Status == OrderStatus.Filled
            and self.held_option is None
            and self.Portfolio[self.spy].Invested
        ):
            self.Debug(
                f"{self.Time}: unexpected SPY exercise or assignment fill; "
                "liquidating equity position"
            )
            self.MarketOrder(self.spy, -self.Portfolio[self.spy].Quantity)

