            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol}, price={order_event.FillPrice}.")
                self.held_contract = None
                self.entry_price = None
                self.exit_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled, OrderStatus.Invalid
            ):
                self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug("Unexpected option exercise or assignment received; liquidating SPY.")
        if self.Portfolio[self.spy].Invested:
            self.Liquidate(self.spy, "Exercise or assignment handling")

    def _entry_is_open(self):
        return self.entry_ticket is not None and self.entry_ticket.Status in (
            OrderStatus.Submitted, OrderStatus.PartiallyFilled
        )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate.date() if hasattr(candidate, "date") else candidate

