from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyLongCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.current_bucket = None
        self.bucket_bars = []
        self.previous_fast = None
        self.previous_slow = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.profit_target_price = None

        self.no_entry_date = None
        self.profit_target_percent = 0.50

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position()

        if self.held_option is not None:
            expiry = self.held_option.ID.Date.date()

            if self.Time.date() >= expiry:
                if self.Portfolio[self.held_option].Invested:
                    self._liquidate_option("expiration processing")
                self.no_entry_date = self.Time.date()

            else:
                self._evaluate_option_exit(slice, expiry)

        self._process_spy_minute_bar(slice)

    def _process_spy_minute_bar(self, slice: Slice):
        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        local_end = bar.EndTime.ConvertTo(self.TimeZone)

        if local_end.time() < time(9, 31) or local_end.time() > time(16, 0):
            return

        if local_end.time() == time(16, 0):
            return

        minute = local_end.hour * 60 + local_end.minute
        if minute < 9 * 60 + 31 or minute > 15 * 60 + 59:
            return

        bucket_index = (minute - (9 * 60 + 31)) // 5
        bucket_key = (local_end.date(), bucket_index)

        if self.current_bucket != bucket_key:
            self.current_bucket = bucket_key
            self.bucket_bars = []

        expected_minute = 9 * 60 + 31 + bucket_index * 5 + len(self.bucket_bars)

        if minute != expected_minute:
            self.bucket_bars = []
            self.current_bucket = bucket_key
            expected_minute = 9 * 60 + 31 + bucket_index * 5

        if minute != expected_minute:
            return

        self.bucket_bars.append(bar)

        if len(self.bucket_bars) != 5:
            return

        if local_end.minute != 35 and local_end.minute != 0 and local_end.minute != 5:
            return

        close = self.bucket_bars[-1].Close
        self.fast.Update(local_end, close)
        self.slow.Update(local_end, close)

        current_fast = self.fast.Current.Value
        current_slow = self.slow.Current.Value

        bullish = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        if (
            bullish
            and time(9, 45) <= local_end.time() <= time(14, 30)
        ):
            self._try_enter(slice, close, local_end.date())

    def _try_enter(self, slice: Slice, spy_price: float, algorithm_date):
        if algorithm_date == self.no_entry_date:
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and not self.entry_ticket.Status.IsClosed():
            return

        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            return

        chain = slice.OptionChains.get(self.spy_option.Symbol)
        if chain is None:
            self.Debug("Skipped selection: no SPY option chain.")
            return

        eligible_expirations = sorted(
            {
                contract.ID.Date.date()
                for contract in chain
                if contract.ID.Date.date() >= algorithm_date + timedelta(days=7)
            }
        )

        if not eligible_expirations:
            self.Debug("Skipped selection: no expiration at least seven calendar days away.")
            return

        expiration = eligible_expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.ID.Date.date() == expiration
            and contract.ID.OptionStyle == OptionStyle.American
            and contract.ID.OptionRight == OptionRight.Call
            and contract.ID.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped selection: no qualifying call contract.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.ID.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol} "
            f"expiration={expiration} strike={selected.ID.Strike}"
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_option = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.profit_target_price = (
                    self.entry_price * (1.0 + self.profit_target_percent)
                )
                self.Debug(
                    f"Entry filled: {self.held_option} "
                    f"price={self.entry_price}"
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} "
                    f"price={order_event.FillPrice}"
                )
                self.exit_ticket = None
                self.held_option = None
                self.entry_price = None
                self.profit_target_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.exit_ticket = None

        if order_event.OrderType == OrderType.OptionExercise:
            self.Debug(f"Unexpected option exercise or assignment: {order_event.Symbol}")

    def _evaluate_option_exit(self, slice: Slice, expiration):
        if self.held_option is None:
            return

        holding = self.Portfolio[self.held_option]
        if not holding.Invested:
            return

        local_time = self.Time.time()
        previous_trading_day = self._previous_trading_day(expiration)

        time_stop = (
            self.Time.date() == previous_trading_day
            and local_time >= time(15, 45)
        )

        quote = slice.QuoteBars.get(self.held_option)
        target_hit = False

        if quote is not None:
            bid = quote.Bid.Close
            ask = quote.Ask.Close

            if bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2.0
                target_hit = midpoint >= self.profit_target_price

        if time_stop:
            self._liquidate_option("expiration time stop")
        elif target_hit:
            self._liquidate_option("profit target")

    def _liquidate_option(self, reason: str):
        if self.held_option is None:
            return

        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            return

        if self.entry_ticket is not None and not self.entry_ticket.Status.IsClosed():
            self.Transactions.CancelOrder(self.entry_ticket.OrderId)

        self.exit_ticket = self.Liquidate(self.held_option)
        self.Debug(f"Exit submitted: {reason} symbol={self.held_option}")

    def _handle_unexpected_spy_position(self):
        spy_holding = self.Portfolio[self.spy]
        if spy_holding.Invested:
            self.Debug(
                f"Unexpected SPY equity position detected; liquidating "
                f"quantity={spy_holding.Quantity}"
            )
            self.MarketOrder(self.spy, -spy_holding.Quantity)

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate
