        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        duration = bar.EndTime - bar.Time

        # Reject partial or cross-session bars; never synthesize missing bars.
        if duration != timedelta(minutes=5):
            return

        if bar.Time.time() < time(9, 30) or bar.EndTime.time() > time(16, 0):
            return

        if len(self.slow_values) == self.slow_values.maxlen:
            self.previous_fast = sum(list(self.fast_values)[-5:]) / 5.0
            self.previous_slow = sum(self.slow_values) / 20.0

        self.fast_values.append(float(bar.Close))
        self.slow_values.append(float(bar.Close))

        if len(self.fast_values) == 5 and len(self.slow_values) == 20:
