            current_slow = sum(self.slow_values) / 20.0

            eligible_time = time(9, 45) <= bar.EndTime.time() <= time(14, 30)

            if (
                eligible_time
                and self.previous_fast is not None
                and self.previous_slow is not None
                and self.previous_fast <= self.previous_slow
                and current_fast > current_slow
            ):
                self.pending_signal = True

    def OnData(self, slice):
        self.HandleUnexpectedEquityPosition()
        self.HandleExpirationProcessing()

        if self.entry_symbol is not None:
            self.EvaluateProfitTarget(slice)
            self.EvaluateTimeStop()

        if self.pending_signal:
            self.pending_signal = False
            self.TryEnter(slice)

    def TryEnter(self, slice):
        if self.entry_ticket is not None:
            return

        if self.entry_symbol is not None and self.Portfolio[self.entry_symbol].Invested:
            return

        if self.no_entry_expiration_date == self.Time.date():
            return

        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        current_price = float(self.Securities[self.spy].Price)
        if current_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        current_date = self.Time.date()
        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= current_date + timedelta(days=7)
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration satisfies the 7-day rule.")
            return

        expiration_date = expirations[0]
        minimum_strike = current_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == expiration_date
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        candidates.sort(key=lambda contract: (float(contract.Strike), str(contract.Symbol)))
        selected = candidates[0]

        self.entry_symbol = selected.Symbol
        self.no_entry_expiration_date = None
