        if not self.Portfolio[self.entry_symbol].Invested:
            return

        security = slice.Bars.get(self.entry_symbol)
        if security is None:
            security = slice.QuoteBars.get(self.entry_symbol)

        if security is None:
            return

        bid = getattr(security, "Bid", 0)
        ask = getattr(security, "Ask", 0)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (float(bid) + float(ask)) / 2.0
        target_price = self.entry_price * (1.0 + self.PROFIT_TARGET)

        if midpoint >= target_price:
            self.CancelOpenExitOrder()
            self.exit_ticket = self.Liquidate(self.entry_symbol)
            self.Debug(
                "Profit-target exit submitted: {} midpoint {:.4f}".format(
                    self.entry_symbol, midpoint
                )
            )

    def EvaluateTimeStop(self):
        if self.entry_symbol is None or self.exit_ticket is not None:
            return
        if not self.Portfolio[self.entry_symbol].Invested:
            return

        expiry_date = self.entry_symbol.ID.Date.date()
        previous_trading_day = expiry_date - timedelta(days=1)

        while (
            previous_trading_day.weekday() >= 5
            or not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
                previous_trading_day
            )
        ):
            previous_trading_day -= timedelta(days=1)

        if (
            self.Time.date() == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self.CancelOpenExitOrder()
            self.exit_ticket = self.Liquidate(self.entry_symbol)
            self.no_entry_expiration_date = self.Time.date()
            self.Debug("Expiration time-stop exit submitted.")

    def HandleExpirationProcessing(self):
        if self.entry_symbol is None:
            return

        expiry_date = self.entry_symbol.ID.Date.date()
        if self.Time.date() >= expiry_date:
            self.no_entry_expiration_date = self.Time.date()

            if self.Portfolio[self.entry_symbol].Invested and self.exit_ticket is None:
                self.exit_ticket = self.Liquidate(self.entry_symbol)
                self.Debug("Expiration-protection exit submitted.")

    def HandleUnexpectedEquityPosition(self):
        if self.Portfolio[self.spy].Invested:
            self.Debug("Unexpected SPY equity position; liquidating immediately.")
            self.Liquidate(self.spy)

    def CancelOpenExitOrder(self):
        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Canceling prior exit order.")
            self.exit_ticket = None
