from AlgorithmImports import *
from datetime import timedelta


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw,
            extendedMarketHours=False
        )

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-500, 500)
                .Expiration(0, 365)
        )

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator("SPY", self.consolidator)

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.previous_fast = None
        self.previous_slow = None
        self.signal_pending = False

        self.held_option = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_price = None
        self.no_entry_date = None

        # Profit target: option midpoint reaches 150% of filled entry price.
        self.profit_target_multiple = 1.50

    def OnFiveMinuteBar(self, sender, bar):
        bar_end = Extensions.ConvertToUtc(bar.EndTime, self.TimeZone).astimezone(
            TimeZoneInfo.FindSystemTimeZoneById("Eastern Standard Time")
        )

        if bar_end.hour < 9 or (bar_end.hour == 9 and bar_end.minute < 35):
            return
        if bar_end.hour > 16 or (bar_end.hour == 16 and bar_end.minute > 0):
            return

        prior_fast = self.fast.Current.Value if self.fast.IsReady else None
        prior_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        current_fast = self.fast.Current.Value
        current_slow = self.slow.Current.Value

        eligible_time = (
            (bar_end.hour > 9 or (bar_end.hour == 9 and bar_end.minute >= 45))
            and (bar_end.hour < 14 or (bar_end.hour == 14 and bar_end.minute <= 30))
        )

        if (
            eligible_time
            and prior_fast is not None
            and prior_slow is not None
            and prior_fast <= prior_slow
            and current_fast > current_slow
        ):
            self.signal_pending = True

    def OnData(self, slice):
        self.HandleUnexpectedSpyPosition()

        if self.held_option is not None:
            self.EvaluateExit(slice)

        self.consolidator.Update(slice["SPY"])

        if self.signal_pending:
            self.signal_pending = False
            self.TryEnter(slice)

    def TryEnter(self, slice):
        today = self.Time.date()

        if self.no_entry_date == today:
            return
        if self.held_option is not None:
            return
        if self.entry_ticket is not None and not self.entry_ticket.Status.IsClosed():
            return
        if not self.option_symbol_has_chain(slice):
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        current_price = self.Securities["SPY"].Price
        if current_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        minimum_expiration = today + timedelta(days=7)
        candidates = []

        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Expiry.date() >= minimum_expiration:
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped entry: no expiration at least seven calendar days away.")
            return

        selected_expiry = min(c.Expiry.date() for c in candidates)
        target_strike = current_price * 1.01

        contracts = [
            c for c in candidates
            if c.Expiry.date() == selected_expiry
            and c.Right == OptionRight.Call
            and c.Strike >= target_strike
        ]

        if not contracts:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        selected = min(contracts, key=lambda c: (c.Strike, str(c.Symbol)))
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)

        self.Debug(
            "Entry submitted: {0}, expiry {1}, strike {2}".format(
                selected.Symbol, selected.Expiry.date(), selected.Strike
            )
        )

    def EvaluateExit(self, slice):
        if self.held_option is None or self.entry_price is None:
            return

        symbol = self.held_option
        holding = self.Portfolio[symbol]

        if not holding.Invested:
            return

        today = self.Time.date()
        expiry_date = symbol.ID.Date.date()
        preceding_day = expiry_date - timedelta(days=1)

        if today >= expiry_date:
            self.SubmitExit("expiration processing")
            self.no_entry_date = today
            return

        if today == preceding_day and self.Time.hour == 15 and self.Time.minute >= 45:
            self.SubmitExit("expiration time stop")
            self.no_entry_date = today
            return

        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            return

        contract = None
        for chain in slice.OptionChains.Values:
            for item in chain:
                if item.Symbol == symbol:
                    contract = item
                    break
            if contract is not None:
                break

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * self.profit_target_multiple:
            self.SubmitExit("profit target")

    def SubmitExit(self, reason):
        if self.held_option is None:
            return

        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            self.Transactions.CancelOrder(self.exit_ticket.OrderId)

        quantity = -self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(self.held_option, quantity)
        self.Debug("Exit submitted: {0} ({1})".format(self.held_option, reason))

    def OnOrderEvent(self, order_event):
        if order_event.Status != OrderStatus.Filled:
            return

        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            self.held_option = order_event.Symbol
            self.entry_price = order_event.FillPrice
            self.Debug(
                "Entry filled: {0} at {1}".format(
                    order_event.Symbol, order_event.FillPrice
                )
            )

        elif self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            self.Debug(
                "Exit filled: {0} at {1}".format(
                    order_event.Symbol, order_event.FillPrice
                )
            )
            self.held_option = None
            self.entry_price = None
            self.exit_ticket = None
            self.entry_ticket = None

    def HandleUnexpectedSpyPosition(self):
