        eligible = time(9, 45) <= barTime <= time(14, 30)

        bullish = (
            self.previousFast is not None
            and self.previousSlow is not None
            and self.previousFast <= self.previousSlow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        self.pendingEntrySignal = bool(
            eligible and bullish and self.entryTicket is None
            and self.heldOption is None
            and not self.Portfolio.Invested
        )
        self.signalPrice = float(bar.Close) if self.pendingEntrySignal else None

