        self.HandleUnexpectedSpyPosition()

        if self.heldOption is not None and self.Portfolio[self.heldOption].Invested:
            self.EvaluateHeldOption(slice)
            self.ProcessExpirationDay()
        elif self.heldOption is not None:
            self.heldOption = None
            self.entryPrice = None

        if self.pendingEntrySignal:
            self.pendingEntrySignal = False
            self.TryEnter(slice)

