            contract.Expiry.date() for contract in eligibleContracts
        )

        underlyingPrice = self.signalPrice
        if underlyingPrice is None or underlyingPrice <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        minimumStrike = underlyingPrice * 1.01
        candidates = [
            contract for contract in eligibleContracts
            if contract.Expiry.date() == expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimumStrike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entryTicket = self.MarketOrder(selected.Symbol, 1)
