        if self.heldOption is None or self.exitTicket is not None:
            return

        if self.entryTicket is not None and not self.entryTicket.Status.IsClosed:
            return

        quantity = self.Portfolio[self.heldOption].Quantity
        if quantity == 0:
            return

        self.CancelOpenExitOrders()
        self.exitTicket = self.MarketOrder(
            self.heldOption, -quantity, tag=reason
        )
        self.Debug("Exit submitted: {}.".format(reason))

    def CancelOpenExitOrders(self):
        if self.exitTicket is not None and not self.exitTicket.Status.IsClosed:
            self.exitTicket.Cancel("Replacing exit order")
            self.exitTicket = None

    def OnOrderEvent(self, orderEvent):
        if self.entryTicket is not None and orderEvent.OrderId == self.entryTicket.OrderId:
            if orderEvent.Status == OrderStatus.Filled:
                self.heldOption = orderEvent.Symbol
                self.entryPrice = orderEvent.FillPrice
                self.entryTicket = None
                self.Debug(
