                self.entryTicket = None

        if self.exitTicket is not None and orderEvent.OrderId == self.exitTicket.OrderId:
            if orderEvent.Status == OrderStatus.Filled:
                self.Debug(
                    "Exit filled: {} at {:.4f}.".format(
                        orderEvent.Symbol, orderEvent.FillPrice
                    )
                )
                self.exitTicket = None
                self.heldOption = None
                self.entryPrice = None
            elif orderEvent.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self.exitTicket = None

    def HandleUnexpectedSpyPosition(self):
        quantity = self.Portfolio[self.spySymbol].Quantity
        if quantity != 0 and self.previousSpyQuantity == 0:
            self.Debug(
                "Unexpected SPY exercise or assignment; liquidating equity."
            )
            self.MarketOrder(self.spySymbol, -quantity)

    def PreviousTradingDay(self, date):
        candidate = date - timedelta(days=1)
        while candidate.weekday() >= 5:
            candidate -= timedelta(days=1)
        return candidate

    def OnEndOfAlgorithm(self):
        if self.heldOption is not None and self.Portfolio[self.heldOption].Invested:
            self.MarketOrder(
                self.heldOption,
                -self.Portfolio[self.heldOption].Quantity,
                tag="final liquidation"
            )

