from datetime import datetime, timedelta, time


class SpyBullishCallAlgorithm(QCAlgorithm):
    PROFIT_TARGET_MULTIPLE = 2.0

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 730)
        )
        self.option_symbol = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.blocked_entry_dates = set()
        self.pending_signal_time = None
        self.last_spy_quantity = 0

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        self.previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        self.previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not (self.fast.IsReady and self.slow.IsReady):
            return

        bar_time = bar.EndTime.time()
        if time(9, 45) <= bar_time <= time(14, 30):
            if (
                self.previous_fast is not None
                and self.previous_slow is not None
                and self.previous_fast <= self.previous_slow
                and self.fast.Current.Value > self.slow.Current.Value
            ):
                self.pending_signal_time = bar.EndTime

    def OnData(self, slice):
        self._liquidate_unexpected_spy_position()

        held_symbol = self._held_option_symbol()

        if held_symbol is not None:
            self._process_option_exit(held_symbol, slice)

        if self.pending_signal_time is not None:
            signal_time = self.pending_signal_time
            self.pending_signal_time = None

            if (
                signal_time.date() == self.Time.date()
                and signal_time.time() <= time(14, 30)
                and self.Time.date() not in self.blocked_entry_dates
            ):
                if held_symbol is None and not self._entry_order_open():
                    self._try_enter(slice)

    def _try_enter(self, slice):
        if self.option_symbol not in slice.OptionChains:
            self.Debug("Skipped call selection: no option chain.")
            return

        chain = slice.OptionChains[self.option_symbol]
        current_date = self.Time.date()
        spy_price = self.Securities[self.spy].Price

        if spy_price <= 0:
            self.Debug("Skipped call selection: invalid SPY price.")
            return

        expirations = sorted(
            {
                contract.Expiry.date()
                for contract in chain
                if contract.Expiry.date() >= current_date + timedelta(days=7)
            }
        )

        if not expirations:
            self.Debug("Skipped call selection: no valid expiration.")
            return

        selected_expiry = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped call selection: no qualifying call.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self.entry_symbol = selected.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Call entry submitted: {0}, expiry {1}, strike {2}".format(
                selected.Symbol, selected_expiry, selected.Strike
            )
        )

    def _process_option_exit(self, symbol, slice):
        security = self.Securities[symbol]
        expiry_date = symbol.ID.Date.date()
        today = self.Time.date()

        if today >= expiry_date:
            self.blocked_entry_dates.add(today)
            self._submit_exit(symbol, "expiration processing")
            return

        if (
            today == expiry_date - timedelta(days=1)
            and self.Time.time() >= time(15, 45)
        ):
            self.blocked_entry_dates.add(today)
            self._submit_exit(symbol, "pre-expiration time stop")
            return

        if self.exit_ticket is not None and not self._order_finished(self.exit_ticket):
            return

        quote = slice.QuoteBars.get(symbol)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if self.entry_price is not None and midpoint >= self.entry_price * self.PROFIT_TARGET_MULTIPLE:
            self._submit_exit(symbol, "profit target")

    def _submit_exit(self, symbol, reason):
        if self.exit_ticket is not None and not self._order_finished(self.exit_ticket):
            return

        if self.entry_ticket is not None and not self._order_finished(self.entry_ticket):
            return

        quantity = self.Portfolio[symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(symbol, -quantity)
        self.Debug("Call exit submitted ({0}): {1}".format(reason, symbol))

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.Debug(
                    "Call entry filled: {0} at {1}".format(
                        self.entry_symbol, self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Error,
            ):
                self.entry_ticket = None
                self.entry_symbol = None
                self.entry_price = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Call exit filled: {0} at {1}".format(
                    order_event.Symbol, order_event.FillPrice
                ))
                self.exit_ticket = None
                self.entry_ticket = None
                self.entry_symbol = None
                self.entry_price = None

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug("Unexpected option exercise or assignment detected.")
        self._liquidate_unexpected_spy_position()

    def _held_option_symbol(self):
        if self.entry_symbol is not None and self.Portfolio[self.entry_symbol].Invested:
            return self.entry_symbol

        for symbol, holding in self.Portfolio.items():
            if symbol.SecurityType == SecurityType.Option and holding.Invested:
                return symbol

        return None

    def _entry_order_open(self):
        return (
            self.entry_ticket is not None
            and not self._order_finished(self.entry_ticket)
        )

    def _order_finished(self, ticket):
        return ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.Error,
        )

    def _liquidate_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.Debug("Unexpected SPY equity position; liquidating immediately.")
            self.MarketOrder(self.spy, -quantity)
            self.last_spy_quantity = 0
        else:
            self.last_spy_quantity = 0
